#!/usr/bin/env python3
"""Detailed magnetics documentation from design_values.json (core comparison, winding, insulation, tests)."""
import os, sys, json, math
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE); sys.path.insert(0, ROOT)
from tools.dab import magnetics as MG
V = json.load(open(os.path.join(ROOT, "04_Design_Calculations", "design_values.json")))
xf, xfi, ind = V["transformer"], V["transformer_integrated_leakage"], V["inductor"]
fs, n, L = V["spec"]["fs"], V["spec"]["n"], V["L"]
I1, I2, P = V["nominal"]["Irms1"], V["nominal"]["Irms2"], V["spec"]["P"]
R = []; w = R.append
w("# 06 - High-frequency transformer and series inductor\n\n_Generated by `transformer_design.py` from the design values; see 03 for the models._\n")
w("## 1. Core material and geometry comparison (100 kHz, square-wave, Bpk 0.13 T target)\n")
w("| core | material | N1:N2 | Bpk (T) | core loss (W) | copper loss (W) | bundle fill (copper fill = 0.5x) | leakage interleaved (uH) | dT (K) | volume (cm3) |\n|---|---|---|---|---|---|---|---|---|---|")
for core in ("E55/28/21", "ETD59/31/22", "E65/32/27", "PQ65/60", "E70/33/32"):
    for mat in ("3C95", "N97"):
        t = MG.design_transformer(800, 400, n, fs, I1, I2, P, core=core, material=mat, Bpk_target=0.13)
        w(f"| {core} | {mat} | {t['N1']}:{t['N2']} | {t['Bpk']:.3f} | {t['P_core']:.1f} | {t['P_cu']:.1f} | {t['fill']:.2f}{'' if t['fill_ok'] else ' (!)'} | {t['Llk']*1e6:.1f} | {t['dT']:.0f} | {t['Ve']*1e6:.0f} |")
w("\nSelection: **E65/32/27 pair, 3C95** - lowest total loss with a feasible fill factor and 14 K rise; E55 does not fit the window, E70/PQ65 add volume without benefit. "
  "Planar alternative: a planar E64 with 4-layer PCB windings would need 28 turns of 2 mm2 (two 70 um layers in parallel per turn ... > 24 layers) - not practical at 800 V / 28 turns; "
  "planar construction is attractive only for n ~ 1 low-turn-count designs, so the conventional litz/bobbin construction is retained.\n")
w("## 2. Selected transformer\n")
w(f"| item | value |\n|---|---|\n| core | 2 x E65/32/27, 3C95, ungapped (Lm ~ {MG.MU0*3000*xf['N1']**2*xf['Ae']/MG.CORES['E65/32/27']['le']*1e3:.1f} mH) |\n"
  f"| turns | N1 = {xf['N1']}, N2 = {xf['N2']} (n = {n:.0f}) |\n| primary wire | litz {xf['strands1']} x 0.1 mm ({xf['A1']*1e6:.2f} mm2), {xf['layers1']} layers |\n"
  f"| secondary wire | litz {xf['strands2']} x 0.1 mm ({xf['A2']*1e6:.2f} mm2), {xf['layers2']} layers |\n| arrangement | P/2 - S - P/2 interleaved; 3 x 50 um polyimide between P and S (reinforced), 6 mm margins |\n"
  f"| skin depth at 100 kHz, 100 C | {xf['delta']*1e3:.3f} mm |\n| Rac/Rdc | primary {xf['Fr1']:.2f}, secondary {xf['Fr2']:.2f} |\n| Bpk at 800 V | {xf['Bpk']:.3f} T (Bsat 0.41 T at 100 C) |\n"
  f"| core loss | {xf['P_core']:.1f} W (Steinmetz x iGSE 1.22) |\n| copper loss | {xf['P_cu']:.1f} W at {I1:.1f} / {I2:.1f} A rms |\n| temperature rise | {xf['dT']:.0f} K at 3 m/s |\n"
  f"| leakage (HV side) | {xf['Llk']*1e6:.1f} uH interleaved, {xfi['Llk']*1e6:.1f} uH non-interleaved |\n| interwinding capacitance | {xf['C_iw']*1e12:.0f} pF |\n| window fill | {xf['fill']:.2f} |\n")
w("## 3. Integrated leakage option\n")
w(f"The non-interleaved winding gives {xfi['Llk']*1e6:.0f} uH ({100*xfi['Llk']/L:.0f} % of the {L*1e6:.0f} uH needed) with {xfi['P_cu']/xf['P_cu']:.2f}x the copper loss. "
  "A deliberate leakage layer (3 mm spacer between P and S) would reach ~40 uH but the tolerance on leakage of a hand-wound bobbin transformer is +/-20 %, "
  "which maps directly into +/-20 % power capability (eq. 4). The baseline keeps the leakage small and uses the discrete gapped inductor whose value is set by the gap (+/-5 %).\n")
w("## 4. Series inductor\n")
w(f"| item | value |\n|---|---|\n| core | 2 x {ind['core']}, 3C95, gapped {ind['gap']*1e3:.2f} mm (centre leg, fringing correction to be measured) |\n| inductance | {V['L_ext']*1e6:.1f} uH |\n"
  f"| turns | {ind['N']} x litz {ind['strands']} x 0.1 mm, {ind['layers']} layers, kept 3 mm from the gap |\n| Bpk at 1.2 x I_pk | {ind['Bpk']:.3f} T |\n| stored energy | {ind['E']*1e3:.1f} mJ |\n"
  f"| core loss | {ind['P_core']:.1f} W |\n| copper loss | {ind['P_cu']:.1f} W (Rac/Rdc {ind['Fr']:.2f} incl. fringing) |\n| fill | {ind['fill']:.2f} |\n")
w("## 5. Insulation system (HV-LV basic, 850 V working, see 15_Safety_Reliability)\n")
w("* Bobbin: glass-filled PBT/PET, CTI >= 400, 6 mm flanges; primary and secondary on separate bobbin halves is NOT used (interleaving needs a single bobbin), so the\n"
  "  interwinding insulation is 3 layers of 50 um polyimide tape (each layer rated > 5 kV) plus 6 mm margin tape at both ends: creepage along the bobbin > 12 mm.\n"
  "* Lead-outs: triple-insulated wire (TIW) for the primary exits, secondary litz with 0.4 mm PFA sleeve.\n"
  "* High-frequency stress: the 100 kHz square voltage (dv/dt ~ 20 V/ns at the edges) drives displacement current through C_iw (~0.6 nF): i = C dv/dt ~ 12 A peak pulses - the\n"
  "  Y-capacitors and the EMI filter (14) return this current; partial-discharge inception is not expected below 1 kV peak across 150 um polyimide but must be tested.\n"
  "* Core bonded to the heatsink/chassis (PE) through a thermal pad; the core is at protective-earth potential, so the primary-to-core and secondary-to-core insulation is also basic (850 V / 450 V).\n")
w("## 6. Test procedure (before assembly on the PCB)\n")
w("1. Turns ratio and polarity (1 kHz, 1 V): N1/N2 = 2.00 +/- 1 %.\n2. Lm at 100 kHz, 1 V: expect 10 mH class (ungapped 3C95), record; leakage with the secondary shorted: expect < 6 uH.\n"
  f"3. Winding resistance (4-wire): compare with the calculated DC values (R1 = {xf['R1dc']*1e3:.1f} mOhm, R2 = {xf['R2dc']*1e3:.1f} mOhm).\n4. Interwinding capacitance at 100 kHz.\n"
  "5. Hipot: 2.5 kVrms 60 s primary-secondary and 2.5 kVrms primary-core / secondary-core (basic, 850 V working); partial discharge screening at 1.5 x working voltage if the lab has the equipment.\n"
  "6. Thermal run at rated current (back-to-back test with a second unit or on the converter at reduced voltage) - record hot-spot with a thermocouple under the outer layer.\n"
  "7. Inductor: L at 0, 10, 20 A DC bias (must stay within -10 % at 24 A), gap measurement, hipot 1.5 kVrms winding-core.\n")
open(os.path.join(HERE, "magnetics_design.md"), "w").write("\n".join(R) + "\n")
print("\n".join(R)[:2500])
